pub fn moyenne_entiere(v: &[i32]) -> Option<i32> {
    if v.is_empty() {
        return None;
    }

    let len = v.len() as i64;
    let sum: i64 = v.iter().map(|&x| x as i64).sum();

    // Division entière vers zéro : Rust fait déjà cela pour les entiers signés
    // avec l'opérateur /, mais on doit faire attention au signe.
    // sum / len fait une division entière vers zéro pour les i64, ce qui est correct.
    Some((sum / len) as i32)
}

